namespace Weaviate.Client.Tests.Integration;

using Microsoft.Extensions.Configuration;
using Weaviate.Client;

/// <summary>
/// Base class for RBAC integration tests. Connects to the RBAC-enabled Weaviate instance.
/// Configurable via WV_TEST_RBAC_HOST, WV_TEST_RBAC_REST_PORT, WV_TEST_RBAC_GRPC_PORT
/// (defaulting to localhost:8092 / 50063).
/// </summary>
public abstract class RbacIntegrationTests : IntegrationTests
{
    /// <summary>The API key for the built-in admin user on the RBAC server.</summary>
    protected const string ADMIN_API_KEY = "admin-key";

    /// <inheritdoc />
    public override string RestHost =>
        _configuration.GetValue<string>("WV_TEST_RBAC_HOST") ?? "localhost";

    /// <inheritdoc />
    public override ushort RestPort =>
        _configuration.GetValue<ushort>("WV_TEST_RBAC_REST_PORT", 8092);

    /// <inheritdoc />
    public override ushort GrpcPort =>
        _configuration.GetValue<ushort>("WV_TEST_RBAC_GRPC_PORT", 50063);

    /// <inheritdoc />
    public override ICredentials? Credentials => Auth.ApiKey(ADMIN_API_KEY);
}

# Backup API Usage Guide

This guide covers the Weaviate C# client's backup and restore functionality. It provides examples and best practices for using the modern, idiomatic backup API.

## Table of Contents

- [Overview](#overview)
- [Backend Configuration](#backend-configuration)
- [Creating Backups](#creating-backups)
- [Restoring Backups](#restoring-backups)
- [Monitoring Operations](#monitoring-operations)
- [Concurrency and Coordination](#concurrency-and-coordination)
- [Advanced Usage](#advanced-usage)

## Overview

The Backup API allows you to create and restore backups of your Weaviate collections. Backups can be stored on various backend storage providers, including the local filesystem, S3, GCS, and Azure Blob Storage.

Key features include:

- **Type-safe operations**: Separate `BackupCreateOperation` and `BackupRestoreOperation` types.
- **Type-safe backends**: Separate `FilesystemBackend` and `ObjectStorageBackend` types.
- **Automatic cleanup**: Resources are automatically disposed of when operations complete.
- **Flexible patterns**: Async tracking, sync blocking, or fire-and-forget.
- **Configurable timeouts**: Global defaults with per-call overrides.

## Backend Configuration

Backends are configured using the static factory methods on the `BackupBackend` class. Supported backends include:

### Filesystem Backend

```csharp
var backend = BackupBackend.Filesystem(path: "/backups");
Console.WriteLine(backend.Provider); // BackupStorageProvider.Filesystem
```

### Object Storage Backends

#### S3

```csharp
var backend = BackupBackend.S3(bucket: "my-backup-bucket", path: "backups/");
Console.WriteLine(backend.Provider); // BackupStorageProvider.S3
```

#### Google Cloud Storage

```csharp
var backend = BackupBackend.GCS(bucket: "my-gcs-bucket", path: "weaviate-backups");
Console.WriteLine(backend.Provider); // BackupStorageProvider.GCS
```

#### Azure Blob Storage

```csharp
var backend = BackupBackend.Azure(bucket: "my-container", path: "backups");
Console.WriteLine(backend.Provider); // BackupStorageProvider.Azure
```

## Creating Backups

To create a backup, use the `BackupClient.Create` method. This returns a `BackupCreateOperation` object that can be used to track the operation's status.

### Creating Backup Example

```csharp
var operation = await client.Backups.Create(new BackupCreateRequest(
    id: "my-backup-id",
    backend: BackupBackend.Filesystem(path: "/backups")
));

await operation.WaitForCompletion();
Console.WriteLine(operation.Current.Status); // BackupStatus.Success
```

## Restoring Backups

To restore a backup, use the `BackupClient.Restore` method. This returns a `BackupRestoreOperation` object.

### Restoring Backup Example

```csharp
var operation = await client.Backups.Restore(new BackupRestoreRequest(
    id: "my-backup-id",
    backend: BackupBackend.Filesystem(path: "/backups")
));

await operation.WaitForCompletion();
Console.WriteLine(operation.Current.Status); // BackupStatus.Success
```

## Monitoring Operations

Both `BackupCreateOperation` and `BackupRestoreOperation` support:

- **Status polling**: Use the `Current` property to get the latest status.
- **Cancellation**: Call the `Cancel` method to abort the operation.

### Monitoring Operation Example

```csharp
var operation = await client.Backups.Create(new BackupCreateRequest(
    id: "my-backup-id",
    backend: BackupBackend.Filesystem(path: "/backups")
));

while (!operation.IsCompleted)
{
    Console.WriteLine(operation.Current.Status);
    await Task.Delay(1000);
}
```

## Concurrency and Coordination

**Important:** Concurrent backup or restore operations are not allowed. Attempting to start a new operation while another is in progress will throw a `WeaviateBackupConflictException`.

To perform multiple operations, ensure each one is awaited to completion before starting the next.

### Sequential Operations Example

```csharp
// Create the first backup
var operation1 = await client.Backups.Create(new BackupCreateRequest(
    id: "backup-1",
    backend: BackupBackend.Filesystem(path: "/backups")
));
await operation1.WaitForCompletion();

// Create the second backup after the first completes
var operation2 = await client.Backups.Create(new BackupCreateRequest(
    id: "backup-2",
    backend: BackupBackend.Filesystem(path: "/backups")
));
await operation2.WaitForCompletion();
```

## Advanced Usage

### Configurable Timeouts

You can configure global defaults for polling intervals and timeouts using `BackupClient.Config`:

```csharp
BackupClient.Config = new BackupClientConfig
{
    PollInterval = TimeSpan.FromMilliseconds(500),
    Timeout = TimeSpan.FromMinutes(5)
};
```

### Selective Backup/Restore

Include or exclude specific collections:

```csharp
var operation = await client.Backups.Create(new BackupCreateRequest(
    id: "my-backup-id",
    backend: BackupBackend.Filesystem(path: "/backups"),
    Include = new[] { "Collection1", "Collection2" }
));
await operation.WaitForCompletion();
```

#!/usr/bin/env python3
"""Self-tests for check_xml_param_docs.py.

Dependency-free (no pytest in this repo): run with `python3 ci/test_check_xml_param_docs.py`.
Each case pins one of the defects the checker previously had.
"""

from __future__ import annotations

import importlib.util
import io
import re
import tempfile
from contextlib import redirect_stderr, redirect_stdout
from pathlib import Path

HERE = Path(__file__).resolve().parent

_spec = importlib.util.spec_from_file_location("chk", HERE / "check_xml_param_docs.py")
assert _spec is not None, "could not build a module spec for check_xml_param_docs.py"
assert _spec.loader is not None, "module spec for check_xml_param_docs.py has no loader"
chk = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(chk)

FAILURES: list[str] = []


def check(label: str, condition: bool, detail: str = "") -> None:
    if condition:
        print(f"  PASS  {label}")
    else:
        print(f"  FAIL  {label}{(': ' + detail) if detail else ''}")
        FAILURES.append(label)


def decls(source: str):
    return list(chk.iter_declarations(source))


# ---------------------------------------------------------------- defect 1
# Generic methods were invisible: `(?P<name>\w+)\s*\(` cannot match `Hybrid<T>(`.
GENERIC_SRC = """
public static class Ext
{
    /// <summary>
    /// Performs a hybrid search.
    /// </summary>
    /// <param name="client">The client</param>
    public static Task<int> Hybrid<T>(this Client client, string query)
    {
        return null;
    }
}
"""


def test_generic_methods() -> None:
    print("defect 1 - generic methods are scanned")
    found = decls(GENERIC_SRC)
    names = [d[1] for d in found]
    check("Hybrid<T> is discovered", "Hybrid<T>" in names, f"got {names}")
    # and, being discovered, its missing param is reported
    with tempfile.TemporaryDirectory() as td:
        p = Path(td) / "QueryClient.Generic.cs"
        p.write_text(GENERIC_SRC, encoding="utf-8")
        issues, scanned = chk.check_file(p, root=Path(td))
    check(
        "the generic overload is the one declaration counted in the file",
        scanned == 1,
        f"got {scanned}",
    )
    check(
        "undocumented 'query' on the generic overload is reported",
        any("missing <param> for: query" in i for i in issues),
        f"got {issues}",
    )


# ---------------------------------------------------------------- defect 2
# Splitting the parameter list on every comma turned `Dictionary<string, object>`
# into a phantom parameter named `Dictionary<string` that no doc tag can satisfy.
def test_generic_parameter_types() -> None:
    print("defect 2 - commas inside generic type arguments")
    names = chk.parse_param_names(
        "Dictionary<string, object> filters, IList<KeyValuePair<int, string>> pairs, int limit"
    )
    check(
        "generic args do not create phantom parameters",
        names == ["filters", "pairs", "limit"],
        f"got {names}",
    )
    check(
        "no phantom 'Dictionary<string' parameter",
        not any("<" in n for n in names),
        f"got {names}",
    )


# ---------------------------------------------------------------- defect 3
# Zero scanned files printed OK and exited 0, so any path drift silently
# disabled the gate forever.
def test_empty_scan_fails() -> None:
    print("defect 3 - an empty scan fails loudly")
    with tempfile.TemporaryDirectory() as td:
        empty = Path(td) / "src" / "Weaviate.Client"
        empty.mkdir(parents=True)
        err = io.StringIO()
        with redirect_stdout(io.StringIO()), redirect_stderr(err):
            rc = chk.main(root=Path(td), client_root=empty)
    check("exit code is non-zero when 0 files are scanned", rc != 0, f"rc={rc}")
    check(
        "message explains the misconfiguration",
        "scanned 0 files" in err.getvalue(),
        f"stderr={err.getvalue()!r}",
    )


def test_missing_client_root_fails() -> None:
    print("defect 3b - a missing client root fails loudly")
    with tempfile.TemporaryDirectory() as td:
        err = io.StringIO()
        with redirect_stdout(io.StringIO()), redirect_stderr(err):
            rc = chk.main(root=Path(td), client_root=Path(td) / "does" / "not" / "exist")
    check("exit code is non-zero when the client root is absent", rc != 0, f"rc={rc}")
    check(
        "message names the missing root",
        "client root not found" in err.getvalue(),
        f"stderr={err.getvalue()!r}",
    )


# ---------------------------------------------------------------- defect 4
# Nested parens in a default value, a tuple return type, and parens/brackets
# inside an attribute string all defeated the `[^)]*` signature capture.
NESTED_SRC = """
public class C
{
    /// <summary>Does a thing.</summary>
    /// <param name="query">The query</param>
    /// <param name="cancellationToken">The cancellation token</param>
    public Task<int> WithDefaultParen(
        string query,
        CancellationToken cancellationToken = [REDACTED]
    )
    {
        return null;
    }

    /// <summary>Does a thing.</summary>
    /// <param name="query">The query</param>
    public Task<(int Count, string Name)> WithTupleReturn(string query)
    {
        return null;
    }

    /// <summary>Does a thing.</summary>
    /// <param name="query">The query</param>
    [Obsolete("use Other(x) instead [see docs]")]
    public Task<int> WithTrickyAttribute(string query)
    {
        return null;
    }
}
"""


def test_nested_parens_and_attributes() -> None:
    print("defect 4 - nested parens, tuple returns, tricky attributes")
    found = {d[1]: d[2] for d in decls(NESTED_SRC)}
    check(
        "method with `= default(CancellationToken)` is scanned",
        "WithDefaultParen" in found,
        f"got {sorted(found)}",
    )
    if "WithDefaultParen" in found:
        names = chk.parse_param_names(found["WithDefaultParen"])
        check(
            "its parameters parse correctly",
            names == ["query", "cancellationToken"],
            f"got {names}",
        )
    check(
        "method with a tuple return type is scanned",
        "WithTupleReturn" in found,
        f"got {sorted(found)}",
    )
    check(
        "method behind an attribute containing parens/brackets in a string is scanned",
        "WithTrickyAttribute" in found,
        f"got {sorted(found)}",
    )


# ------------------------------------------------- regression: no bad parses
TYPE_CONSTRAINT_SRC = """
/// <summary>
/// The typed query client
/// </summary>
public partial class TypedQueryClient<T>
    where T : class, new()
{
}
"""


def test_type_constraint_is_not_a_method() -> None:
    print("regression - a type's `where T : class, new()` is not a method")
    names = [d[1] for d in decls(TYPE_CONSTRAINT_SRC)]
    check("no phantom `new` declaration", "new" not in names, f"got {names}")


def test_real_tree_is_clean() -> None:
    print("integration - the real client tree passes")
    out = io.StringIO()
    with redirect_stdout(out), redirect_stderr(out):
        rc = chk.main()
    text = out.getvalue().strip()
    check("checker exits 0 on the current tree", rc == 0, text)
    m = re.search(r"(\d+) declaration\(s\) in (\d+) file\(s\)", text)
    check("it reports what it scanned", m is not None, text)
    if m:
        check(
